public static class TestsExcelEditing {
 static int count;static string dir;static readonly BindingFlags FI=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Assert(bool value,string name){if(!value)throw new Exception("FAIL: "+name);count++;Console.WriteLine("PASS: "+name);}
 static object Field(object obj,string name){return obj.GetType().GetField(name,FI).GetValue(obj);}
 static object Call(object obj,string name,params object[] args){var value=obj.GetType().GetMethod(name,FI).Invoke(obj,args);Application.DoEvents();return value;}
 static DataRow Row(DataTable t,string col,string id){return t.AsEnumerable().First(r=>Model.Val(r,col)==id);}
 static void Select(DataGridView g,int row,string column){g.CurrentCell=g.Rows[row].Cells[column];g.ClearSelection();g.CurrentCell.Selected=true;g.Focus();}
 static IEnumerable<Control> Children(Control parent){foreach(Control child in parent.Controls){yield return child;foreach(var nested in Children(child))yield return nested;}}
 static void Shot(Form f,string name){using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(0,0,f.Width,f.Height));image.Save(Path.Combine(dir,name));}}
 [STAThread] public static int Main(string[] args){try{dir=args[0];Directory.CreateDirectory(dir);CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;Application.EnableVisualStyles();var parsed=ClipboardTable.Parse("001\t\"两行\n备注\"\r\n002\t\"双\"\"引号\"\r\n");Assert(parsed.Count==2&&parsed[0][0]=="001"&&parsed[0][1]=="两行\n备注"&&parsed[1][1]=="双\"引号","Excel TSV quoting newlines and leading zeros parsed");Assert(ClipboardTable.Parse("\t")[0].Count==2,"empty pasted cells preserved");bool rejected=false;try{ClipboardTable.Parse("\"bad");}catch{rejected=true;}Assert(rejected,"incomplete quote rejected");
  using(var f=new MainWindow()){f.Opacity=0;f.ShowInTaskbar=false;f.Show();var sheets=new List<Sheet>{(Sheet)typeof(TestsV13).GetMethod("Input",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null)};typeof(MainWindow).GetField("sheets",FI).SetValue(f,sheets);var choice=(ComboBox)Field(f,"sheetChoice");typeof(MainWindow).GetField("busy",FI).SetValue(f,true);choice.Items.Add("Excel操作演示");choice.SelectedIndex=0;typeof(MainWindow).GetField("busy",FI).SetValue(f,false);Call(f,"LoadSelected");var m=(Model)Field(f,"model");var check=(DataGridView)Field(f,"checkGrid");var adjust=(DataGridView)Field(f,"adjustGrid");var pay=(DataGridView)Field(f,"payGrid");var warning=(DataGridView)Field(f,"warningGrid");Assert(new[]{check,adjust,pay,warning}.All(g=>g.RowHeadersVisible&&g.ContextMenuStrip.Items.OfType<ToolStripMenuItem>().Any(i=>i.Text.StartsWith("粘贴"))),"row numbers and paste menu on all tables");Assert(check.Columns.Cast<DataGridViewColumn>().All(c=>c.SortMode==DataGridViewColumnSortMode.Programmatic),"header selects column rather than sorting");
  Select(check,0,"一口价（无手续费）");Call(f,"PasteText","25\r\n15");Assert((decimal)m.Check.Rows[0][7]==25m&&(decimal)m.Check.Rows[1][7]==15m,"multirow clipboard paste");Call(f,"Undo");Assert(m.Check.Rows[0].IsNull(7)&&m.Check.Rows[1].IsNull(7),"whole paste undo is one operation");Call(f,"Redo");Assert((decimal)m.Check.Rows[0][8]==215m&&(decimal)m.Check.Rows[1][8]==25m,"paste redo restores derived calculations");Select(check,0,"一口价（无手续费）");rejected=false;try{Call(f,"PasteText","10\r\nBAD");}catch(TargetInvocationException){rejected=true;}Assert(rejected&&(decimal)m.Check.Rows[0][7]==25m&&(decimal)m.Check.Rows[1][7]==15m,"invalid paste leaves every cell untouched");
  Select(check,0,"转化数");Call(f,"PasteText","2\t29\t999\t10\t888\t备注甲");Assert((decimal)m.Check.Rows[0][4]==2m&&(decimal)m.Check.Rows[0][5]==29m&&(decimal)m.Check.Rows[0][6]==58m&&(decimal)m.Check.Rows[0][8]==48m&&Model.Val(m.Check.Rows[0],"备注")=="备注甲","rectangular paste skips derived columns and recalculates");Call(f,"Undo");Assert((decimal)m.Check.Rows[0][4]==8m&&(decimal)m.Check.Rows[0][7]==25m,"rectangular paste undo restores all fields");
  Call(check,"OnColumnHeaderMouseClick",new DataGridViewCellMouseEventArgs(1,-1,0,0,new MouseEventArgs(MouseButtons.Left,1,0,0,0)));Assert(check.SelectedCells.Count==check.Rows.Count&&GridCopy.SelectionText(check)=="T1\r\nT1\r\nT2\r\nT3","header click selects copyable whole column");Call(check,"OnRowHeaderMouseClick",new DataGridViewCellMouseEventArgs(-1,2,0,0,new MouseEventArgs(MouseButtons.Left,1,0,0,0)));Assert(check.SelectedCells.Count==check.Columns.Cast<DataGridViewColumn>().Count(c=>c.Visible)&&check.SelectedCells.Cast<DataGridViewCell>().All(c=>c.RowIndex==2),"row number selects whole row");
  Select(check,0,"备注");Call(f,"PasteText","向下复制");check.ClearSelection();check.Rows[0].Cells[9].Selected=true;check.Rows[1].Cells[9].Selected=true;check.Focus();Assert((bool)Call(f,"ExcelShortcut",Keys.Control|Keys.D),"Ctrl D shortcut handled");Assert(Model.Val(m.Check.Rows[1],"备注")=="向下复制","fill down applies upper value");Call(f,"Undo");Assert(Model.Val(m.Check.Rows[1],"备注")!="向下复制","fill down undo");Select(check,0,"备注");Assert((bool)Call(f,"ExcelShortcut",Keys.Delete)&&Model.Val(m.Check.Rows[0],"备注")=="","Delete clears cell without removing row");Call(f,"Undo");Assert(Model.Val(m.Check.Rows[0],"备注")=="向下复制","Delete clear undo");
  int oldRows=m.Check.Rows.Count;Call(f,"AddBlankRow");Assert(m.Check.Rows.Count==oldRows+1&&m.Check.Rows[oldRows].IsNull(7),"add blank row has no dialog");Call(f,"Undo");Assert(m.Check.Rows.Count==oldRows,"blank row undo");Select(check,check.Rows.Count-1,"任务/方案ID");Call(f,"PasteText","T4\t新方案4\t视频\t1\t10\t999\t2\t999\t备注4\r\nT5\t新方案5\t视频\t2\t10\t999\t3\t999\t备注5\r\nT6\t新方案6\t视频\t3\t10\t999\t4\t999\t备注6");Assert(m.Check.Rows.Count==oldRows+2&&(decimal)Row(m.Check,"任务/方案ID","T6")[8]==26m,"paste automatically appends required rows");Call(f,"Undo");Assert(m.Check.Rows.Count==oldRows&&Model.Val(m.Check.Rows[oldRows-1],"任务/方案ID")=="T3","appended paste undo restores original rows");
  var filter=(GridFilter)Field(f,"checkFilter");filter.SelectValues("任务/方案ID",new[]{"T1"});m.Check.DefaultView.Sort="[单价] DESC";Select(check,0,"一口价（无手续费）");Call(f,"PasteText","12\r\n34");Assert((decimal)m.Check.Rows[1][7]==12m&&(decimal)m.Check.Rows[0][7]==34m,"sorted filtered paste targets row identities");Call(f,"Undo");Assert((decimal)m.Check.Rows[1][7]==15m&&(decimal)m.Check.Rows[0][7]==25m,"sorted filtered paste undo");filter.Clear();m.Check.DefaultView.Sort="";
  Call(f,"Navigate",3);Select(adjust,0,"线上成本");Call(f,"PasteText","-123.45\r\n0");Assert((decimal)m.Adjust.Rows[0][4]==-123.45m&&(decimal)m.Adjust.Rows[1][4]==0m,"adjustment paste accepts negative and explicit zero");Call(f,"Undo");Assert((decimal)m.Adjust.Rows[0][4]==1m&&(decimal)m.Adjust.Rows[1][4]==1m,"adjustment paste undo restores corrected net difference");m.Adjust.DefaultView.Sort="";Select(adjust,0,"任务ID");Call(f,"SortCurrentColumn",adjust,"DESC");Assert(Model.Val(((DataRowView)adjust.Rows[0].DataBoundItem).Row,"任务ID")=="T2","right-click sorting retained");
  Call(f,"Navigate",1);Select(pay,0,"姓名(必填)");Call(f,"PasteText","粘贴姓名");Assert(Model.Val(m.Payment.Rows[0],"姓名(必填)")=="粘贴姓名","payment table direct paste");Call(f,"Undo");Assert(Model.Val(m.Payment.Rows[0],"姓名(必填)")=="","payment paste undo");Call(f,"Navigate",2);Select(warning,0,"说明");string original=Model.Val(m.Warnings.Rows[0],"说明");Call(f,"PasteText","人工备注");Assert(Model.Val(m.Warnings.Rows[0],"说明")=="人工备注","warning table direct paste");Call(f,"Undo");Assert(Model.Val(m.Warnings.Rows[0],"说明")==original,"warning paste undo");
  Call(f,"Navigate",0);Select(check,0,"一口价（无手续费）");Call(f,"PasteText","999");Call(f,"SyncAdjustment");m.ExportAdjust(Path.Combine(dir,"excel-paste-adjust.xlsx"));var sheet=Xlsx.Read(Path.Combine(dir,"excel-paste-adjust.xlsx"))[0];sheet.SetHeader(1);int taskRow=sheet.Rows.Keys.Where(r=>r>1).Single(r=>sheet.Get(r,"任务ID")=="T1");Assert(sheet.Get(taskRow,"线上成本")=="1014","pasted fixed prices sync and actually export task sum");var total=(Label)Field(f,"adjustTotal");Assert(total.Text=="调差总金额：1,015.00 元","total after sync");var af=(GridFilter)Field(f,"adjustFilter");af.SelectValues("任务ID",new[]{"T1"});Application.DoEvents();Assert(total.Text.Contains("1,015.00")&&total.Text.Contains("当前显示：1,014.00"),"filtered amount separate from overall total");af.Clear();Select(adjust,0,"线上成本");Call(f,"PasteText","-12.34");decimal expected=m.Adjust.AsEnumerable().Where(r=>!r.IsNull(4)).Sum(r=>(decimal)r[4]);Assert(total.Text=="调差总金额："+expected.ToString("N2")+" 元","manual negative paste updates total");Call(f,"Undo");Assert(total.Text=="调差总金额：1,015.00 元","undo updates total");Call(f,"Redo");Assert(total.Text=="调差总金额："+expected.ToString("N2")+" 元","redo updates total");Call(f,"Undo");f.WindowState=FormWindowState.Maximized;Call(f,"FitScreen");foreach(int page in new[]{0,1,2,3}){Call(f,"Navigate",page);var title=(Label)Field(f,"heading");Assert(title.ClientSize.Height>=TextRenderer.MeasureText(title.Text,title.Font).Height,"125 percent heading fits page "+page);var notices=Children(f).OfType<Label>().Where(l=>l.Name=="NoticeText"&&l.Visible).ToArray();Assert(notices.All(l=>l.ClientSize.Height-l.Padding.Vertical>=TextRenderer.MeasureText("测",l.Font).Height),"125 percent notice text fits page "+page);var gf=page==0?(GridFilter)Field(f,"checkFilter"):page==1?(GridFilter)Field(f,"payFilter"):page==3?af:null;if(gf!=null)Assert(gf.Host.Controls.Cast<Control>().All(c=>gf.Host.ClientRectangle.Contains(c.Bounds)),"125 percent filter controls contained page "+page);}Call(f,"Navigate",3);Shot(f,"ui-excel-editing.png");f.Hide();}
  Console.WriteLine("TOTAL "+count+" Excel style editing assertions passed");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
